from functions import extract_pdf_text
import re

pdf_path = "/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/e9a2c537-8232-4c3f-85b0-b52de6bcba99.pdf"
text = extract_pdf_text(pdf_path)
lines = [ln.strip() for ln in text.split('\n') if ln.strip()]

status_tokens = {"available", "checked out", "overdue"}
riordan_variants = {"rick riordan", "riordan, rick"}

results = []
for i, ln in enumerate(lines):
    if ln.lower() in riordan_variants:
        # try to find title by scanning up to 2 lines above for a non-header
        title = None
        for j in range(i-1, max(i-3, -1), -1):
            if lines[j].lower() not in {"title", "author", "publisher", "genre", "status"} and not re.match(r"^books$|^young", lines[j].lower()):
                title = lines[j]
                break
        # find the first status token within next 6 lines
        status = None
        for k in range(i+1, min(i+7, len(lines))):
            tok = lines[k].lower()
            if tok in status_tokens:
                status = lines[k]
                break
        if title and status:
            results.append((title, status))

# de-duplicate by title (keep the last seen status)
by_title = {}
for t, s in results:
    by_title[t] = s

not_on = [ (t,s) for (t,s) in by_title.items() if s.lower() in ("checked out", "overdue") ]
print("Expanded validation count not on shelves:", len(not_on))
for t, s in sorted(not_on):
    print(f"{t} - {s}")
